29	async function graphql<T>(token: string, query: string, variables: Record<string, unknown>): Promise<T> {
30	  const resp = await fetch(GH_GRAPHQL, {
31	    method: 'POST',
32	    headers: {
33	      Authorization: `bearer ${token}`,
34	      'Content-Type': 'application/json',
35	    },
36	    body: JSON.stringify({ query, variables }),
37	  });
38	
39	  if (!resp.ok) {
40	    throw new Error(`GitHub API HTTP ${resp.status}: ${resp.statusText}`);
41	  }
42	
43	  const json = (await resp.json()) as { data?: T; errors?: { message: string }[] };
44	
45	  if (json.errors?.length) {
46	    throw new Error(`GitHub GraphQL: ${json.errors.map((e) => e.message).join(', ')}`);
47	  }
48	
49	  if (!json.data) {
50	    throw new Error('GitHub GraphQL: no data returned');
51	  }
52	
53	  return json.data;
54	}
