56	// Query to fetch open PRs from a repo, with their closing issue references
57	// Used to find PRs that fix board issues but aren't directly tracked on the board
58	const REPO_OPEN_PRS_QUERY = `
59	query GetRepoOpenPRs($owner: String!, $repo: String!, $cursor: String) {
60	  repository(owner: $owner, name: $repo) {
61	    pullRequests(states: OPEN, first: 50, after: $cursor) {
62	      pageInfo { hasNextPage endCursor }
63	      nodes {
64	        number title url state isDraft createdAt updatedAt
65	        additions deletions headRefName
66	        author { login avatarUrl }
67	        assignees(first: 10) { nodes { login avatarUrl } }
68	        repository { name owner { login } }
69	        commits(last: 1) { nodes { commit { statusCheckRollup { state } } } }
70	        reviews(last: 5) { nodes { state author { login avatarUrl } } }
71	        reviewRequests(first: 10) { nodes { requestedReviewer { ... on User { login avatarUrl } } } }
72	        closingIssuesReferences(first: 20) { nodes { number } }
73	      }
74	    }
75	  }
76	}
77	`;
78	
79	// The big GraphQL query - works for both org and user
80	// Note: body is NOT fetched here (too large) — loaded on demand via fetchItemBody
81	const PROJECT_ITEMS_QUERY = `
82	query GetProjectItems($login: String!, $number: Int!, $isOrg: Boolean!, $cursor: String) {
83	  viewer { login }
84	  org: organization(login: $login) @include(if: $isOrg) {
85	    projectV2(number: $number) {
86	      title
87	      items(first: 100, after: $cursor) {
88	        pageInfo { hasNextPage endCursor }
89	        nodes {
90	          id
91	          type
92	          fieldValues(first: 20) {
93	            nodes {
94	              ... on ProjectV2ItemFieldSingleSelectValue {
95	                name
96	                field { ... on ProjectV2SingleSelectField { name } }
97	              }
98	              ... on ProjectV2ItemFieldIterationValue {
99	                title
100	                field { ... on ProjectV2IterationField { name } }
101	              }
102	            }
103	          }
104	          content {
105	            ... on Issue {
106	              __typename
107	              number title url state createdAt updatedAt
108	              author { login avatarUrl }
109	              assignees(first: 10) { nodes { login avatarUrl } }
110	              labels(first: 10) { nodes { name color } }
111	              milestone { title number dueOn }
112	              repository { name owner { login } }
113	            }
114	            ... on PullRequest {
115	              __typename
116	              number title url state isDraft createdAt updatedAt
117	              additions deletions headRefName
118	              author { login avatarUrl }
119	              assignees(first: 10) { nodes { login avatarUrl } }
120	              labels(first: 10) { nodes { name color } }
121	              milestone { title number dueOn }
122	              repository { name owner { login } }
123	              commits(last: 1) {
124	                nodes { commit { statusCheckRollup { state } } }
125	              }
126	              reviews(last: 5) {
127	                nodes { state author { login avatarUrl } }
128	              }
129	              reviewRequests(first: 10) {
130	                nodes { requestedReviewer { ... on User { login avatarUrl } } }
131	              }
132	              closingIssuesReferences(first: 10) {
133	                nodes { number }
134	              }
135	            }
136	          }
137	        }
138	      }
139	    }
140	  }
141	  user: user(login: $login) @skip(if: $isOrg) {
142	    projectV2(number: $number) {
143	      title
144	      items(first: 100, after: $cursor) {
145	        pageInfo { hasNextPage endCursor }
146	        nodes {
147	          id
148	          type
149	          fieldValues(first: 20) {
150	            nodes {
151	              ... on ProjectV2ItemFieldSingleSelectValue {
152	                name
153	                field { ... on ProjectV2SingleSelectField { name } }
154	              }
155	              ... on ProjectV2ItemFieldIterationValue {
156	                title
157	                field { ... on ProjectV2IterationField { name } }
158	              }
159	            }
160	          }
161	          content {
162	            ... on Issue {
163	              __typename
164	              number title url state createdAt updatedAt
165	              author { login avatarUrl }
166	              assignees(first: 10) { nodes { login avatarUrl } }
167	              labels(first: 10) { nodes { name color } }
168	              milestone { title number dueOn }
169	              repository { name owner { login } }
170	            }
171	            ... on PullRequest {
172	              __typename
173	              number title url state isDraft createdAt updatedAt
174	              additions deletions headRefName
175	              author { login avatarUrl }
176	              assignees(first: 10) { nodes { login avatarUrl } }
177	              labels(first: 10) { nodes { name color } }
178	              milestone { title number dueOn }
179	              repository { name owner { login } }
180	              commits(last: 1) {
181	                nodes { commit { statusCheckRollup { state } } }
182	              }
183	              reviews(last: 5) {
184	                nodes { state author { login avatarUrl } }
185	              }
186	              reviewRequests(first: 10) {
187	                nodes { requestedReviewer { ... on User { login avatarUrl } } }
188	              }
189	              closingIssuesReferences(first: 10) {
190	                nodes { number }
191	              }
192	            }
193	          }
194	        }
195	      }
196	    }
197	  }
198	}
199	`;
