272	function extractColumn(node: RawProjectNode, statusFieldName: string): string {
273	  const nodes = node.fieldValues?.nodes ?? [];
274	  for (const fv of nodes) {
275	    if (fv.field?.name === statusFieldName && fv.name) {
276	      return fv.name;
277	    }
278	  }
279	  return 'Uncategorized';
280	}
281	
282	function extractSprint(node: RawProjectNode): { sprint: string; sprintField: string } | undefined {
283	  for (const fv of node.fieldValues?.nodes ?? []) {
284	    if (fv.title !== undefined && fv.field?.name) {
285	      return { sprint: fv.title, sprintField: fv.field.name };
286	    }
287	  }
288	  return undefined;
289	}
290	
291	function extractLatestReviews(rawReviews: { nodes: Array<{ state: string; author: GHUser }> } | null | undefined): ReviewInfo[] {
292	  const byReviewer = new Map<string, ReviewInfo>();
293	  for (const r of rawReviews?.nodes ?? []) {
294	    if (r?.author) {
295	      byReviewer.set(r.author.login, { state: r.state as ReviewInfo['state'], author: r.author });
296	    }
297	  }
298	  return Array.from(byReviewer.values());
299	}
