301	function parseItem(node: RawProjectNode, column: string): BoardItem | null {
302	  // Skip null content and Draft Issues (type: DraftIssue) — they lack standard fields
303	  if (!node.content || !('__typename' in node.content) || (node.content.__typename !== 'Issue' && node.content.__typename !== 'PullRequest')) {
304	    return null;
305	  }
306	  const c = node.content as RawIssue | RawPR;
307	
308	  const base = {
309	    id: node.id,
310	    column,
311	    author: c.author ?? { login: 'unknown', avatarUrl: '' },
312	    assignees: c.assignees?.nodes ?? [],
313	    labels: c.labels?.nodes ?? [],
314	    repository: c.repository?.name ?? '',
315	    repositoryOwner: c.repository?.owner?.login ?? '',
316	    createdAt: c.createdAt,
317	    updatedAt: c.updatedAt,
318	    body: undefined, // loaded on demand via fetchBody
319	    milestone: c.milestone
320	      ? { title: c.milestone.title, number: c.milestone.number, dueOn: c.milestone.dueOn }
321	      : undefined,
322	    ...(() => {
323	      const s = extractSprint(node);
324	      return s ? { sprint: s.sprint, sprintField: s.sprintField } : {};
325	    })(),
326	  };
327	
328	  if (c.__typename === 'Issue') {
329	    return {
330	      ...base,
331	      number: c.number,
332	      title: c.title,
333	      type: 'ISSUE',
334	      url: c.url,
335	      state: c.state,
336	    };
337	  }
338	
339	  if (c.__typename === 'PullRequest') {
340	    const pr = c as RawPR;
341	    const ciRaw = pr.commits?.nodes?.[0]?.commit?.statusCheckRollup?.state ?? 'none';
342	    return {
343	      ...base,
344	      number: pr.number,
345	      title: pr.title,
346	      type: 'PULL_REQUEST',
347	      url: pr.url,
348	      state: pr.state,
349	      isDraft: pr.isDraft,
350	      additions: pr.additions,
351	      deletions: pr.deletions,
352	      headRefName: pr.headRefName,
353	      ciState: ciRaw as CIState,
354	      reviews: extractLatestReviews(pr.reviews),
355	      reviewRequests: (pr.reviewRequests?.nodes ?? [])
356	        .map((r) => r.requestedReviewer)
357	        .filter((r): r is GHUser => r !== null),
358	      closingIssueNumbers: (pr.closingIssuesReferences?.nodes ?? []).map((n) => n.number),
359	    };
360	  }
361	
362	  return null;
363	}
