365	interface RawRepoPR {
366	  number: number;
367	  title: string;
368	  url: string;
369	  state: string;
370	  isDraft: boolean;
371	  createdAt: string;
372	  updatedAt: string;
373	  additions: number;
374	  deletions: number;
375	  headRefName: string;
376	  author: GHUser | null;
377	  assignees: { nodes: GHUser[] } | null;
378	  repository: { name: string; owner: { login: string } } | null;
379	  commits: { nodes: Array<{ commit: { statusCheckRollup: { state: string } | null } }> } | null;
380	  reviews: { nodes: Array<{ state: string; author: GHUser }> } | null;
381	  reviewRequests: { nodes: Array<{ requestedReviewer: GHUser | null }> } | null;
382	  closingIssuesReferences: { nodes: Array<{ number: number }> } | null;
