385	/**
386	 * For each repo that has board issues, fetch all open PRs and return those
387	 * that close (via `Fixes #N`, `Closes #N`, etc.) a board issue.
388	 * The linked PR inherits the parent issue's column and sprint.
389	 */
390	async function fetchLinkedPRsFromRepos(
391	  token: string,
392	  issueByRepo: Map<string, Map<number, BoardItem>>,
393	  groups: Record<string, BoardItem[]>
394	): Promise<BoardItem[]> {
395	  const linkedPRMap = new Map<string, BoardItem>(); // `owner/repo#number` → BoardItem
396	  // Track PR numbers already on the board to avoid duplicates
397	  const boardPRKeys = new Set<string>();
398	  for (const items of Object.values(groups)) {
399	    for (const item of items) {
400	      if (item.type === 'PULL_REQUEST') {
401	        boardPRKeys.add(`${item.repositoryOwner}/${item.repository}#${item.number}`);
402	      }
403	    }
404	  }
405	
406	  await Promise.all(
407	    Array.from(issueByRepo.entries()).map(async ([repoKey, issueMap]) => {
408	      const [repoOwner, repoName] = repoKey.split('/');
409	      let prCursor: string | null = null;
410	
411	      do {
412	        let repoData: { repository: { pullRequests: { pageInfo: { hasNextPage: boolean; endCursor: string | null }; nodes: RawRepoPR[] } } } | null = null;
413	        try {
414	          repoData = await graphql<{ repository: { pullRequests: { pageInfo: { hasNextPage: boolean; endCursor: string | null }; nodes: RawRepoPR[] } } }>(
415	            token,
416	            REPO_OPEN_PRS_QUERY,
417	            { owner: repoOwner, repo: repoName, cursor: prCursor }
418	          );
419	        } catch {
420	          break; // skip repos we can't access
421	        }
422	
423	        const prs = repoData?.repository?.pullRequests?.nodes ?? [];
424	        for (const rawPR of prs) {
425	          const prKey = `${repoOwner}/${repoName}#${rawPR.number}`;
426	          if (boardPRKeys.has(prKey) || linkedPRMap.has(prKey)) continue;
427	
428	          // Check if this PR closes any of our board issues
429	          const closingNums = rawPR.closingIssuesReferences?.nodes?.map((n) => n.number) ?? [];
430	          const parentIssue = closingNums.map((n) => issueMap.get(n)).find((i) => i !== undefined);
431	          if (!parentIssue) continue;
432	
433	          const ciRaw = rawPR.commits?.nodes?.[0]?.commit?.statusCheckRollup?.state ?? 'none';
434	          linkedPRMap.set(prKey, {
435	            id: `linked-${prKey}`,
436	            number: rawPR.number,
437	            title: rawPR.title,
438	            type: 'PULL_REQUEST',
439	            url: rawPR.url,
440	            column: parentIssue.column,
441	            state: rawPR.state,
442	            author: rawPR.author ?? { login: 'unknown', avatarUrl: '' },
443	            assignees: rawPR.assignees?.nodes ?? [],
444	            labels: parentIssue.labels,
445	            repository: repoName,
446	            repositoryOwner: repoOwner,
447	            createdAt: rawPR.createdAt,
448	            updatedAt: rawPR.updatedAt,
449	            isDraft: rawPR.isDraft,
450	            additions: rawPR.additions,
451	            deletions: rawPR.deletions,
452	            headRefName: rawPR.headRefName,
453	            ciState: ciRaw as CIState,
454	            reviews: extractLatestReviews(rawPR.reviews),
455	            reviewRequests: (rawPR.reviewRequests?.nodes ?? [])
456	              .map((r) => r.requestedReviewer)
457	              .filter((r): r is GHUser => r !== null),
458	            sprint: parentIssue.sprint,
459	            sprintField: parentIssue.sprintField,
460	          });
461	        }
462	
463	        if (repoData?.repository?.pullRequests?.pageInfo?.hasNextPage) {
464	          prCursor = repoData.repository.pullRequests.pageInfo.endCursor;
465	        } else {
466	          prCursor = null;
467	        }
468	      } while (prCursor !== null);
469	    })
470	  );
471	
472	  return Array.from(linkedPRMap.values());
473	}
