475	export async function fetchProjectData(
476	  owner: string,
477	  projectNumber: number,
478	  isOrg: boolean,
479	  statusFieldName: string
480	): Promise<RunwayData> {
481	  const token = await getToken();
482	  const allNodes: RawProjectNode[] = [];
483	  let projectTitle = '';
484	  let viewerLogin = '';
485	  let cursor: string | null = null;
486	
487	  type ProjectResponse = { viewer: { login: string }; org?: { projectV2: ProjectData }; user?: { projectV2: ProjectData } };
488	  do {
489	    const data: ProjectResponse = await graphql<ProjectResponse>(
490	      token,
491	      PROJECT_ITEMS_QUERY,
492	      { login: owner, number: projectNumber, isOrg, cursor }
493	    );
494	
495	    if (!viewerLogin) viewerLogin = data.viewer?.login ?? '';
496	
497	    const project: ProjectData | undefined = isOrg ? data.org?.projectV2 : data.user?.projectV2;
498	    if (!project) {
499	      throw new Error(`Project #${projectNumber} not found for ${owner}`);
500	    }
501	
502	    projectTitle = project.title;
503	    allNodes.push(...project.items.nodes);
504	
505	    if (project.items.pageInfo.hasNextPage) {
506	      cursor = project.items.pageInfo.endCursor;
507	    } else {
508	      cursor = null;
509	    }
510	  } while (cursor !== null);
511	
512	  // Group items by column; also build a map of issue number -> BoardItem for linking
513	  const groups: Record<string, BoardItem[]> = {};
514	  const sprintsSet = new Set<string>();
515	  // key: `${owner}/${repo}` -> Map<issueNumber, BoardItem>
516	  const issueByRepo = new Map<string, Map<number, BoardItem>>();
517	
518	  for (const node of allNodes) {
519	    const column = extractColumn(node, statusFieldName);
520	    const item = parseItem(node, column);
521	    if (!item) continue;
522	
523	    if (!groups[column]) {
524	      groups[column] = [];
525	    }
526	    groups[column].push(item);
527	    if (item.sprint) sprintsSet.add(item.sprint);
528	
529	    // Track board issues by repo for later PR linking
530	    if (item.type === 'ISSUE' && item.repositoryOwner && item.repository) {
531	      const repoKey = `${item.repositoryOwner}/${item.repository}`;
532	      if (!issueByRepo.has(repoKey)) issueByRepo.set(repoKey, new Map());
533	      issueByRepo.get(repoKey)!.set(item.number, item);
534	    }
535	  }
536	
537	  // Build ordered column list — case-insensitive so "Ready for review" matches "Ready For Review"
538	  const colOrderLower = COLUMN_ORDER.map((c) => c.toLowerCase());
539	  const knownPresent = Object.keys(groups)
540	    .filter((c) => colOrderLower.includes(c.toLowerCase()))
541	    .sort((a, b) => colOrderLower.indexOf(a.toLowerCase()) - colOrderLower.indexOf(b.toLowerCase()));
542	  const extras = Object.keys(groups).filter((c) => !colOrderLower.includes(c.toLowerCase()));
543	  const columns = [...knownPresent, ...extras];
544	
545	  const totalCount = Object.values(groups).reduce((sum, items) => sum + items.length, 0);
546	  // Natural sort descending (Sprint 21 first, Sprint 1 last)
547	  const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' });
548	  const sprints = Array.from(sprintsSet).sort((a, b) => collator.compare(b, a));
549	
550	  // Fetch open PRs from each repo that has board issues, match by closingIssuesReferences
551	  const linkedIssuePRs = await fetchLinkedPRsFromRepos(token, issueByRepo, groups);
552	
553	  return {
554	    projectTitle,
555	    columns,
556	    groups,
557	    sprints,
558	    lastUpdated: new Date().toISOString(),
559	    totalCount,
560	    viewerLogin,
561	    linkedIssuePRs,
562	  };
563	}
564	
565	// Step 1: get linked PRs via closing references + timeline cross-references
566	const LINKED_PRS_QUERY = `
567	query GetLinkedPRs($owner: String!, $repo: String!, $number: Int!) {
568	  repository(owner: $owner, name: $repo) {
569	    issue(number: $number) {
570	      closingPullRequests(first: 10) {
571	        nodes {
572	          number title url state isDraft headRefName
573	          commits(last: 1) { nodes { commit { oid } } }
574	        }
575	      }
576	      timelineItems(first: 25, itemTypes: [CROSS_REFERENCED_EVENT]) {
577	        nodes {
578	          ... on CrossReferencedEvent {
579	            source {
580	              ... on PullRequest {
581	                number title url state isDraft headRefName
582	                commits(last: 1) { nodes { commit { oid } } }
583	              }
584	            }
585	          }
586	        }
587	      }
588	    }
589	  }
590	}
591	`;
592	
593	interface RawLinkedPR {
594	  number: number;
595	  title: string;
596	  url: string;
597	  state: string;
598	  isDraft: boolean;
599	  headRefName: string;
600	  commits: { nodes: Array<{ commit: { oid: string } }> } | null;
601	}
602	
603	interface RawCheckRunResponse {
604	  check_runs: Array<{
605	    name: string;
606	    status: string;
607	    conclusion: string | null;
608	    details_url: string | null;
609	    html_url: string;
610	  }>;
611	  total_count: number;
612	}
613	
614	async function fetchCheckRunsForCommit(token: string, owner: string, repo: string, sha: string): Promise<CheckRun[]> {
615	  const url = `https://api.github.com/repos/${owner}/${repo}/commits/${sha}/check-runs?per_page=50`;
616	  const resp = await fetch(url, {
617	    headers: {
618	      Authorization: `bearer ${token}`,
619	      Accept: 'application/vnd.github+json',
620	    },
621	  });
622	  if (!resp.ok) return [];
623	  const json = (await resp.json()) as RawCheckRunResponse;
624	  return (json.check_runs ?? []).map((r) => ({
625	    name: r.name,
626	    status: r.status.toUpperCase(),
627	    conclusion: r.conclusion ? r.conclusion.toUpperCase() : null,
628	    detailsUrl: r.details_url ?? r.html_url,
629	  }));
630	}
631	
632	export async function fetchLinkedPRChecks(
633	  owner: string,
634	  repo: string,
635	  issueNumber: number
636	): Promise<LinkedPR[]> {
637	  const token = await getToken();
638	  const data = await graphql<{
639	    repository: {
640	      issue: {
641	        closingPullRequests: { nodes: RawLinkedPR[] };
642	        timelineItems: { nodes: Array<{ source?: RawLinkedPR }> };
643	      } | null;
644	    } | null;
645	  }>(token, LINKED_PRS_QUERY, { owner, repo, number: issueNumber });
646	
647	  // Merge closing PRs + timeline cross-references, deduplicate by number
648	  const closing = data.repository?.issue?.closingPullRequests?.nodes ?? [];
649	  const crossRefs = (data.repository?.issue?.timelineItems?.nodes ?? [])
650	    .map((n) => n.source)
651	    .filter((s): s is RawLinkedPR => !!s && 'number' in s);
652	
653	  const seen = new Set<number>();
654	  const merged: RawLinkedPR[] = [];
655	  for (const pr of [...closing, ...crossRefs]) {
656	    if (!seen.has(pr.number)) {
657	      seen.add(pr.number);
658	      merged.push(pr);
659	    }
660	  }
661	
662	  if (!merged.length) return [];
663	
664	  // Fetch check runs for each PR in parallel
665	  const results = await Promise.all(
666	    merged.map(async (pr): Promise<LinkedPR> => {
667	      const sha = pr.commits?.nodes?.[0]?.commit?.oid;
668	      const checkRuns = sha ? await fetchCheckRunsForCommit(token, owner, repo, sha) : [];
669	
670	      // Derive overall CI state from check runs
671	      let ciState: CIState = 'none';
672	      if (checkRuns.length) {
673	        if (checkRuns.some((r) => r.status !== 'COMPLETED')) ciState = 'PENDING';
674	        else if (checkRuns.some((r) => r.conclusion === 'FAILURE' || r.conclusion === 'TIMED_OUT')) ciState = 'FAILURE';
675	        else if (checkRuns.every((r) => r.conclusion === 'SUCCESS' || r.conclusion === 'SKIPPED' || r.conclusion === 'NEUTRAL')) ciState = 'SUCCESS';
676	        else ciState = 'PENDING';
677	      }
678	
679	      return {
680	        number: pr.number,
681	        title: pr.title,
682	        url: pr.url,
683	        state: pr.state,
684	        isDraft: pr.isDraft,
685	        headRefName: pr.headRefName,
686	        ciState,
687	        checkRuns,
688	      };
689	    })
690	  );
691	
692	  return results;
693	}
694	
695	// Fetch the body of a single issue or PR on demand (not loaded in bulk query)
696	const ITEM_BODY_QUERY = `
697	query GetItemBody($owner: String!, $repo: String!, $number: Int!, $isIssue: Boolean!) {
698	  repository(owner: $owner, name: $repo) {
699	    issue(number: $number) @include(if: $isIssue) { body }
700	    pullRequest(number: $number) @skip(if: $isIssue) { body }
701	  }
702	}
703	`;
704	
705	export async function fetchItemBody(
706	  owner: string,
707	  repo: string,
708	  number: number,
709	  isIssue: boolean
710	): Promise<string> {
711	  const token = await getToken();
712	  const data = await graphql<{
713	    repository: {
714	      issue?: { body: string } | null;
715	      pullRequest?: { body: string } | null;
716	    };
717	  }>(token, ITEM_BODY_QUERY, { owner, repo, number, isIssue });
718	
719	  return (isIssue ? data.repository.issue?.body : data.repository.pullRequest?.body) ?? '';
720	}
