14	export class SprintHubPanel {
15	  public static currentPanel: SprintHubPanel | undefined;
16	  private static readonly viewType = 'sprinthub';
17	
18	  private readonly _panel: vscode.WebviewPanel;
19	  private readonly _extensionUri: vscode.Uri;
20	  private readonly _disposables: vscode.Disposable[] = [];
21	  private _refreshTimer: ReturnType<typeof setInterval> | undefined;
22	
23	  public static createOrShow(extensionUri: vscode.Uri) {
24	    const column = vscode.window.activeTextEditor
25	      ? vscode.window.activeTextEditor.viewColumn
26	      : undefined;
27	
28	    if (SprintHubPanel.currentPanel) {
29	      SprintHubPanel.currentPanel._panel.reveal(column);
30	      return;
31	    }
32	
33	    const panel = vscode.window.createWebviewPanel(
34	      SprintHubPanel.viewType,
35	      'SprintHub',
36	      column ?? vscode.ViewColumn.One,
37	      {
38	        enableScripts: true,
39	        retainContextWhenHidden: true,
40	        localResourceRoots: [vscode.Uri.joinPath(extensionUri, 'out')],
41	      }
42	    );
43	
44	    SprintHubPanel.currentPanel = new SprintHubPanel(panel, extensionUri);
45	  }
46	
47	  private constructor(panel: vscode.WebviewPanel, extensionUri: vscode.Uri) {
48	    this._panel = panel;
49	    this._extensionUri = extensionUri;
50	
51	    this._panel.webview.html = this._buildHtml(this._panel.webview);
52	
53	    this._panel.onDidDispose(() => this.dispose(), null, this._disposables);
54	
55	    this._panel.webview.onDidReceiveMessage(
56	      (message: WebviewMessage) => {
57	        switch (message.type) {
58	          case 'refresh':
59	            this._loadData();
60	            break;
61	          case 'openUrl':
62	            vscode.env.openExternal(vscode.Uri.parse(message.url));
63	            break;
64	          case 'getConfig':
65	            this._sendConfig();
66	            break;
67	          case 'updateConfig':
68	            void this._updateConfig(message.payload);
69	            break;
70	          case 'fetchLinkedPRs':
71	            void this._fetchLinkedPRs(message.itemId, message.owner, message.repo, message.issueNumber);
72	            break;
73	          case 'fetchBody':
74	            void this._fetchBody(message.itemId, message.owner, message.repo, message.number, message.isIssue);
75	            break;
76	        }
77	      },
78	      null,
79	      this._disposables
80	    );
81	
82	    vscode.workspace.onDidChangeConfiguration(
83	      (e) => {
84	        if (e.affectsConfiguration('sprinthub')) {
85	          this._sendConfig();
86	          this._loadData();
87	          this._scheduleRefresh();
88	        }
89	      },
90	      null,
91	      this._disposables
92	    );
93	
94	    this._loadData();
95	    this._sendConfig();
96	    this._scheduleRefresh();
97	  }
98	
99	  private _sendConfig() {
100	    const config = vscode.workspace.getConfiguration('sprinthub');
101	    const payload: RunwayConfig = {
102	      owner: config.get<string>('owner', '').trim(),
103	      projectNumber: config.get<number>('projectNumber', 0),
104	      ownerType: config.get<string>('ownerType', 'organization') as 'organization' | 'user',
105	      statusFieldName: config.get<string>('statusFieldName', 'Status'),
106	      refreshInterval: config.get<number>('refreshInterval', 5),
107	      liquidGlass: config.get<boolean>('liquidGlass', false),
108	      theme: config.get<string>('theme', 'dark') as 'dark' | 'light',
109	      colorBlind: config.get<boolean>('colorBlind', false),
110	    };
111	    this._post({ type: 'config', payload });
112	  }
113	
114	  private async _updateConfig(cfg: RunwayConfig) {
115	    const config = vscode.workspace.getConfiguration('sprinthub');
116	    await Promise.all([
117	      config.update('owner', cfg.owner, vscode.ConfigurationTarget.Global),
118	      config.update('projectNumber', cfg.projectNumber, vscode.ConfigurationTarget.Global),
119	      config.update('ownerType', cfg.ownerType, vscode.ConfigurationTarget.Global),
120	      config.update('statusFieldName', cfg.statusFieldName, vscode.ConfigurationTarget.Global),
121	      config.update('refreshInterval', cfg.refreshInterval, vscode.ConfigurationTarget.Global),
122	      config.update('liquidGlass', cfg.liquidGlass, vscode.ConfigurationTarget.Global),
123	      config.update('theme', cfg.theme, vscode.ConfigurationTarget.Global),
124	      config.update('colorBlind', cfg.colorBlind, vscode.ConfigurationTarget.Global),
125	    ]);
126	  }
127	
128	  private async _fetchLinkedPRs(itemId: string, owner: string, repo: string, issueNumber: number) {
129	    const timeout = new Promise<never>((_, reject) =>
130	      setTimeout(() => reject(new Error('timeout')), 15000)
131	    );
132	    try {
133	      const prs = await Promise.race([fetchLinkedPRChecks(owner, repo, issueNumber), timeout]);
134	      this._post({ type: 'linkedPRs', itemId, prs });
135	    } catch {
136	      this._post({ type: 'linkedPRs', itemId, prs: [] });
137	    }
138	  }
139	
140	  private async _fetchBody(itemId: string, owner: string, repo: string, number: number, isIssue: boolean) {
141	    try {
142	      const body = await fetchItemBody(owner, repo, number, isIssue);
143	      this._post({ type: 'itemBody', itemId, body });
144	    } catch {
145	      this._post({ type: 'itemBody', itemId, body: '' });
146	    }
147	  }
148	
149	  private _scheduleRefresh() {
150	    if (this._refreshTimer) {
151	      clearInterval(this._refreshTimer);
152	    }
153	    const intervalMinutes =
154	      vscode.workspace.getConfiguration('sprinthub').get<number>('refreshInterval', 5);
155	    if (intervalMinutes > 0) {
156	      this._refreshTimer = setInterval(
157	        () => this._loadData(),
158	        intervalMinutes * 60 * 1000
159	      );
160	    }
161	  }
162	
163	  private async _loadData() {
164	    this._post({ type: 'loading' });
165	
166	    const config = vscode.workspace.getConfiguration('sprinthub');
167	    const owner = config.get<string>('owner', '').trim();
168	    const projectNumber = config.get<number>('projectNumber', 0);
169	    const ownerType = config.get<string>('ownerType', 'organization');
170	    const statusFieldName = config.get<string>('statusFieldName', 'Status');
171	
172	    if (!owner || !projectNumber) {
173	      this._post({
174	        type: 'error',
175	        message:
176	          'Please set sprinthub.owner and sprinthub.projectNumber in your VS Code settings (File → Preferences → Settings → search "SprintHub").',
177	      });
178	      return;
179	    }
180	
181	    try {
182	      const data = await fetchProjectData(
183	        owner,
184	        projectNumber,
185	        ownerType === 'organization',
186	        statusFieldName
187	      );
188	      this._post({ type: 'data', payload: data });
189	    } catch (err: unknown) {
190	      const msg = err instanceof Error ? err.message : String(err);
191	      this._post({ type: 'error', message: msg });
192	    }
193	  }
194	
195	  private _post(message: ExtensionMessage) {
196	    this._panel.webview.postMessage(message);
197	  }
198	
199	  private _buildHtml(webview: vscode.Webview): string {
200	    const scriptUri = webview.asWebviewUri(
201	      vscode.Uri.joinPath(this._extensionUri, 'out', 'webview.js')
202	    );
203	    const nonce = getNonce();
204	
205	    return /* html */ `<!DOCTYPE html>
206	<html lang="en">
207	<head>
208	  <meta charset="UTF-8">
209	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
210	  <meta http-equiv="Content-Security-Policy"
211	    content="default-src 'none';
212	             img-src ${webview.cspSource} https: data:;
213	             script-src 'nonce-${nonce}';
214	             style-src ${webview.cspSource} 'unsafe-inline';">
215	  <title>SprintHub</title>
216	</head>
217	<body>
218	  <div id="root"></div>
219	  <script nonce="${nonce}" src="${scriptUri}"></script>
220	</body>
221	</html>`;
222	  }
223	
224	  public dispose() {
225	    SprintHubPanel.currentPanel = undefined;
226	    if (this._refreshTimer) {
227	      clearInterval(this._refreshTimer);
228	    }
229	    this._panel.dispose();
230	    while (this._disposables.length) {
231	      const d = this._disposables.pop();
232	      if (d) d.dispose();
233	    }
234	  }
235	}
