46	  const hasChangesRequested = item.reviews?.some((r) => r.state === 'CHANGES_REQUESTED');
47	  if (hasChangesRequested) return 'Changes Requested';
48	
49	  if (item.ciState === 'FAILURE' || item.ciState === 'ERROR') return 'CI Failing';
50	
51	  const isApproved = item.reviews?.some((r) => r.state === 'APPROVED');
52	  const ciOk = !item.ciState || item.ciState === 'SUCCESS' || item.ciState === 'none' || item.ciState === 'EXPECTED';
53	  if (isApproved && ciOk) return 'Ready to Merge';
54	
55	  // Board column "Ready for review" (case-insensitive) takes priority over generic grouping
56	  if (item.column?.toLowerCase() === 'ready for review') return 'Ready for Review';
57	
58	  // No reviewer assigned at all → clearly needs someone to pick it up
59	  const hasAnyReview = item.reviews?.some(
60	    (r) => r.state === 'APPROVED' || r.state === 'COMMENTED' || r.state === 'CHANGES_REQUESTED'
61	  );
62	  if (!hasAnyReview && !item.reviewRequests?.length) return 'Needs Review';
63	
64	  return 'In Progress';
65	}
